#include <iostream>
#include <string>
#include <array>
#include <string_view>

class GradeBook {
public:
    // C++17 inline static constexpr
    static constexpr size_t students = 5;

    GradeBook(std::string_view name, const std::array<int, students>& gradesArray)
        : courseName(name), grades(gradesArray) {}

    void displayMessage() const {
        std::cout << "Welcome to the grade book for\n" << courseName << "!\n";
    }

    void outputGrades() const {
        std::cout << "The grades are:\n";
        for (size_t student = 0; student < grades.size(); ++student) {
            std::cout << "Student " << (student + 1) << ": " << grades[student] << "\n";
        }
    }

private:
    std::string courseName;
    std::array<int, students> grades;
};

int main() {
    const std::array<int, GradeBook::students> grades = {85, 92, 78, 64, 99};
    GradeBook myGradeBook("CS101 Introduction to C++ Programming", grades);
    myGradeBook.displayMessage();
    myGradeBook.outputGrades();
    return 0;
}

#include <iostream>
#include <iomanip>
#include <array>

void analyzeGrades(const std::array<int, 10>& grades) {
    int lowGrade = 100;
    int highGrade = 0;
    int total = 0;

    std::array<unsigned int, 11> frequency = {}; // zero-initialized

    for (int grade : grades) {
        if (grade < lowGrade) {
            lowGrade = grade;
        }
        if (grade > highGrade) {
            highGrade = grade;
        }
        total += grade;
        ++frequency[grade / 10];
    }

    double average = static_cast<double>(total) / grades.size();

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Class average is " << average << "\n";
    std::cout << "Lowest grade is " << lowGrade << "\n";
    std::cout << "Highest grade is " << highGrade << "\n\n";
    std::cout << "Grade distribution:\n";

    for (size_t count = 0; count < frequency.size(); ++count) {
        if (count == 0) {
            std::cout << "  0-9: ";
        } else if (count == 10) {
            std::cout << "  100: ";
        } else {
            std::cout << (count * 10) << "-" << (count * 10 + 9) << ": ";
        }

        for (unsigned int stars = 0; stars < frequency[count]; ++stars) {
            std::cout << '*';
        }
        std::cout << "\n";
    }
}

int main() {
    const std::array<int, 10> grades = {87, 68, 94, 100, 83, 78, 85, 91, 76, 87};
    analyzeGrades(grades);
    return 0;
}
